            "<style>\n  \n  /* =========================================================\n     class: v-size | attribute: data-size\n     ========================================================= */\n\n  .v-size[data-size='lg'] {\n    width: var(--_size---icon-size--lg);\n  }\n\n  .v-size[data-size='md'] {\n    width: var(--_size---icon-size--xs);\n  }\n\n  .v-size[data-size='base'] {\n    width: var(--_size---icon-size--base);\n  }\n\n  .v-size[data-size='sm'] {\n    width: var(--_size---icon-size--sm);\n  }\n\n  .v-size[data-size='xs'] {\n    width: var(--_size---icon-size--xxs);\n  }\n  \n</style>"
